import math,statistics as st,json
d=['2024-03-01','2024-03-04','2024-03-05','2024-03-06','2024-03-07','2024-03-08']
c={'AAA':[50.0,51.0,50.5,52.0,51.5,53.0],'BBB':[20.0,20.2,20.5,20.6,21.0,21.3]}
r={t:[math.log(v[i]/v[i-1]) for i in range(1,6)] for t,v in c.items()}
v={t:[None,None]+[st.stdev(x[i-2:i])*math.sqrt(252) for i in range(2,5)] for t,x in r.items()}
print(json.dumps(r));print(json.dumps(v))
for t,x in r.items():
  ar=252*st.mean(x);av=math.sqrt(252)*st.stdev(x);print(t,ar,av,ar/av,v[t][-1])
w=1;pk=1;pd=d[0];best=(0,d[0],d[0])
for i in range(1,6):
  w*=c['AAA'][i]/c['AAA'][i-1]
  if w>pk: pk=w;pd=d[i]
  dd=w/pk-1
  if dd<best[0]: best=(dd,pd,d[i])
print(best)
"

